class Box {
    int value; Box shared;
    Box(int value) { this.value = value; }
}

static Box deepCopy(Box original, IdentityHashMap<Box, Box> copies) {
    if (original == null) return null;
    if (copies.containsKey(original)) return copies.get(original);
    Box copy = new Box(original.value);
    copies.put(original, copy);
    copy.shared = deepCopy(original.shared, copies);
    return copy;
}

Box shared = new Box(99);
Box a = new Box(1); a.shared = shared;
Box b = new Box(2); b.shared = shared; // a i b dziela TEN SAM obiekt shared

IdentityHashMap<Box, Box> copies = new IdentityHashMap<>();
Box aCopy = deepCopy(a, copies);
Box bCopy = deepCopy(b, copies);
System.out.println("Kopie 'shared' sa tym samym obiektem: " + (aCopy.shared == bCopy.shared)); // true

