class Node {
    String name; List<Node> neighbors = new ArrayList<>();
    Node(String name) { this.name = name; }
}

Node a = new Node("A"), b = new Node("B"), c = new Node("C");
a.neighbors.add(b); b.neighbors.add(c); c.neighbors.add(a); // cykl A->B->C->A

IdentityHashMap<Node, Boolean> inProgress = new IdentityHashMap<>();
IdentityHashMap<Node, Boolean> done = new IdentityHashMap<>();

static boolean hasCycle(Node node, IdentityHashMap<Node, Boolean> inProgress, IdentityHashMap<Node, Boolean> done) {
    if (inProgress.containsKey(node)) return true;
    if (done.containsKey(node)) return false;
    inProgress.put(node, true);
    for (Node neighbor : node.neighbors) {
        if (hasCycle(neighbor, inProgress, done)) return true;
    }
    inProgress.remove(node);
    done.put(node, true);
    return false;
}

System.out.println("Cykl wykryty: " + hasCycle(a, inProgress, done));

