enum State { START, SAW_A, SAW_B, DONE, ERROR }

EnumMap<State, Map<Character, State>> transitions = new EnumMap<>(State.class);
transitions.put(State.START, Map.of('a', State.SAW_A));
transitions.put(State.SAW_A, Map.of('b', State.SAW_B, 'c', State.DONE));
transitions.put(State.SAW_B, Map.of('b', State.SAW_B, 'c', State.DONE));
transitions.put(State.DONE, Map.of());
transitions.put(State.ERROR, Map.of());

static boolean validate(String input, EnumMap<State, Map<Character, State>> transitions) {
    State current = State.START;
    for (char c : input.toCharArray()) {
        State next = transitions.getOrDefault(current, Map.of()).get(c);
        current = (next != null) ? next : State.ERROR;
    }
    return current == State.DONE;
}

for (String test : new String[]{"abc", "abbbc", "ac", "ba"}) {
    System.out.println(test + " -> " + validate(test, transitions));
}

