enum CacheLevel { L1, L2 }

class TwoTierCache {
    private final EnumMap<CacheLevel, WeakHashMap<Object, String>> levels = new EnumMap<>(CacheLevel.class);
    TwoTierCache() {
        levels.put(CacheLevel.L1, new WeakHashMap<>());
        levels.put(CacheLevel.L2, new WeakHashMap<>());
    }

    void put(Object key, String value) {
        levels.get(CacheLevel.L1).put(key, value);
    }

    String get(Object key) {
        String value = levels.get(CacheLevel.L1).get(key);
        if (value != null) return value;
        value = levels.get(CacheLevel.L2).get(key);
        if (value != null) {
            levels.get(CacheLevel.L1).put(key, value); // promocja L2 -> L1
        }
        return value;
    }
}

TwoTierCache cache = new TwoTierCache();
Object key = new Object();
cache.put(key, "dane");
System.out.println("get z L1: " + cache.get(key));
